<?php

namespace App\Actions\StudyPlans;

use App\Enums\StudyPlanTopicStatus;
use App\Models\StudyPlan;
use App\Models\User;
use Illuminate\Support\Facades\DB;

class ImportStudyPlanFromJson
{
    public function __construct(
        protected FindOrCreateSubject $findOrCreateSubject,
        protected FindOrCreateTopic $findOrCreateTopic,
    ) {}

    /**
     * Create a study plan (and any missing catalog subjects/topics) from
     * a validated JSON payload, typically generated by an AI chat.
     *
     * @param  array{name: string, exam_board: string, goal?: ?string, deadline?: ?string, exam_date?: ?string, subjects: array<int, array{name: string, topics: array<int, string>}>}  $data
     */
    public function handle(array $data, User $actor): StudyPlan
    {
        return DB::transaction(function () use ($data, $actor) {
            $plan = StudyPlan::create([
                'owner_id' => $actor->id,
                'name' => $data['name'],
                'exam_board' => $data['exam_board'],
                'goal' => $data['goal'] ?? null,
                'deadline' => $data['deadline'] ?? null,
                'exam_date' => $data['exam_date'] ?? null,
                'is_public' => false,
            ]);

            foreach ($data['subjects'] as $order => $subjectData) {
                $subject = $this->findOrCreateSubject->handle($subjectData['name'], $actor);

                $planSubject = $plan->studyPlanSubjects()->create([
                    'subject_id' => $subject->id,
                    'order' => $order,
                ]);

                foreach ($subjectData['topics'] as $topicOrder => $topicName) {
                    $topic = $this->findOrCreateTopic->handle($topicName, $subject);

                    $planSubject->studyPlanTopics()->create([
                        'topic_id' => $topic->id,
                        'order' => $topicOrder,
                        'status' => StudyPlanTopicStatus::Pending,
                    ]);
                }
            }

            return $plan;
        });
    }
}
